# Let me verify the rotation function is correct
import json

# Test with a simple 3x3 grid
test_input = [
    [0, 1, 2],
    [3, 4, 5],
    [6, 7, 8]
]

print("Original 3x3:")
for row in test_input:
    print(row)

def build_rotated_input(grid, rotation):
    rows = len(grid)
    cols = len(grid[0])
    if rotation == 0:
        return [row[:] for row in grid]
    elif rotation == 1:
        # 90° CW: (r,c) -> (c, rows-1-r)
        new_grid = [[0] * cols for _ in range(rows)]
        for r in range(rows):
            for c in range(cols):
                new_grid[c][rows - 1 - r] = grid[r][c]
        return new_grid
    elif rotation == 2:
        # 180° CW
        new_grid = [[0] * cols for _ in range(rows)]
        for r in range(rows):
            for c in range(cols):
                new_grid[rows - 1 - r][cols - 1 - c] = grid[r][c]
        return new_grid
    elif rotation == 3:
        # 270° CW
        new_grid = [[0] * cols for _ in range(rows)]
        for r in range(rows):
            for c in range(cols):
                new_grid[rows - 1 - r][c] = grid[c][cols - 1 - r]
        return new_grid

print("\n90° CW (should be col 2 becomes row 0, reversed):")
rot90 = build_rotated_input(test_input, 1)
for row in rot90:
    print(row)

print("\n180° CW (should be rotated 180):")
rot180 = build_rotated_input(test_input, 2)
for row in rot180:
    print(row)

print("\n270° CW (should be col 0 becomes row 0, reversed):")
rot270 = build_rotated_input(test_input, 3)
for row in rot270:
    print(row)

# Now let's build the 2x2 pinwheel
print("\n2x2 pinwheel with 3x3 input:")
n = 3
output = [[0] * (2*n) for _ in range(2*n)]
quadrants = [build_rotated_input(test_input, i) for i in range(4)]
for qr in range(2):
    for qc in range(2):
        for r in range(n):
            for c in range(n):
                output[qr*n + r][qc*n + c] = quadrants[qr][r][c]

for row in output:
    print(row)

